<template><div class="page-shell"><div class="page-title-row"><div><h1 class="page-title">操作日志与审计追溯</h1><p class="page-subtitle">记录规则修改、基础数据维护、告警处理与调度建议等关键操作</p></div><el-button @click="load"><el-icon><Refresh/></el-icon>刷新</el-button></div><div class="glass-card"><el-table :data="filtered" v-loading="loading" height="calc(100vh - 205px)" stripe><el-table-column prop="operationTime" label="操作时间" width="180"><template #default="s">{{s.row.operationTime?.replace('T',' ')}}</template></el-table-column><el-table-column prop="username" label="操作人" width="120"/><el-table-column prop="module" label="模块" width="130"/><el-table-column prop="action" label="操作类型" width="140"/><el-table-column prop="content" label="操作内容" min-width="300" show-overflow-tooltip/><el-table-column prop="ipAddress" label="IP" width="130"/></el-table></div></div></template>
<script setup>import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import api from '../api/client';const rows=ref([]),loading=ref(false);const filtered=computed(()=>rows.value);async function load(){loading.value=true;try{rows.value=await api.get('/logs')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}onMounted(load)</script>
